class Solution:
    def smallestMissingValueSubtree(self, parents, nums):
        n = len(parents)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parents[i]].append(i)
        ans = []
        for i in range(n):
            seen = set()
            stk = [i]
            while stk:
                u = stk.pop()
                seen.add(nums[u])
                stk.extend(children[u])
            mex = 1
            while mex in seen:
                mex += 1
            ans.append(mex)
        return ans

