class Solution {
public:
    vector<int> smallestMissingValueSubtree(vector<int>& parents, vector<int>& nums) {
        int n = parents.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; i++) children[parents[i]].push_back(i);
        vector<int> ans(n, 1);
        int node = -1;
        for (int i = 0; i < n; i++)
            if (nums[i] == 1) { node = i; break; }
        if (node == -1) return ans;
        vector<bool> added(n, false);
        unordered_set<int> seen;
        int mex = 1;
        while (node != -1) {
            vector<int> stk{node};
            while (!stk.empty()) {
                int u = stk.back(); stk.pop_back();
                if (added[u]) continue;
                added[u] = true;
                seen.insert(nums[u]);
                for (int c : children[u]) stk.push_back(c);
            }
            while (seen.count(mex)) mex++;
            ans[node] = mex;
            node = parents[node];
        }
        return ans;
    }
};

